// Renders every post listed in data/blog/index.json (generated by GitHub Pages
// from the .md files in data/blog/). Each post: "# Title", "_author_", "_date_", body.
(function () {
  const container = document.getElementById('blog-list');
  if (!container) return;

  const { index, dir } = container.dataset;
  const readMore = container.dataset.readMore || 'Leer completo';
  const readLess = container.dataset.readLess || 'Ocultar';
  const failed = container.dataset.error || 'No se pudo cargar el blog.';
  const empty = container.dataset.empty || 'Aún no hay artículos.';

  const makeP = text => { const p = document.createElement('p'); p.textContent = text; return p; };

  function buildPost(markdown) {
    const lines = markdown.split('\n').map(l => l.trim()).filter(Boolean);
    const title = (lines.shift() || '').replace(/^#\s*/, '').replace(/[:\s]+$/, '');
    const meta = [];
    while (lines.length && /^_.*_$/.test(lines[0])) {
      meta.push(lines.shift().replace(/^_|_$/g, ''));
    }
    const paragraphs = lines.map(l => l.replace(/^"+|"+$/g, ''));

    const article = document.createElement('article');
    article.className = 'post';

    const h3 = document.createElement('h3');
    h3.textContent = title;
    const metaEl = document.createElement('p');
    metaEl.className = 'meta';
    metaEl.textContent = meta.join(' · ');
    article.append(h3, metaEl);

    const intro = document.createElement('div');
    intro.className = 'body';
    intro.append(makeP(paragraphs[0] || ''));
    article.append(intro);

    if (paragraphs.length > 1) {
      const details = document.createElement('details');
      const summary = document.createElement('summary');
      summary.textContent = readMore;
      const rest = document.createElement('div');
      rest.className = 'body';
      paragraphs.slice(1).forEach(t => rest.append(makeP(t)));
      details.append(summary, rest);
      details.addEventListener('toggle', () => {
        summary.textContent = details.open ? readLess : readMore;
      });
      article.append(details);
    }
    return article;
  }

  fetch(index)
    .then(res => { if (!res.ok) throw new Error(res.status); return res.json(); })
    .then(names => Promise.all(names.map(name =>
      fetch(dir + encodeURIComponent(name))
        .then(res => { if (!res.ok) throw new Error(name + ': ' + res.status); return res.text(); })
        .then(buildPost)
    )))
    .then(posts => {
      if (!posts.length) { container.textContent = empty; return; }
      container.replaceChildren(...posts);
    })
    .catch(err => {
      console.error('Blog load error:', err);
      container.textContent = failed;
    });
})();
